import json
import urllib.request
import urllib.parse
from datetime import datetime, date, timedelta

BASE_URL = "https://api.github.com/search/issues"
HEADERS = {
    "Accept": "application/vnd.github+json",
    "User-Agent": "codex-cli"
}

START_DATE = date(2024, 12, 1)
END_DATE = date(2024, 12, 31)


def _request_json(url: str) -> dict:
    req = urllib.request.Request(url, headers=HEADERS)
    with urllib.request.urlopen(req) as resp:
        return json.load(resp)


def _search(query: str, page: int, per_page: int = 100) -> dict:
    params = {
        "q": query,
        "per_page": per_page,
        "page": page,
    }
    url = f"{BASE_URL}?{urllib.parse.urlencode(params)}"
    return _request_json(url)


def _fetch_all(query: str) -> tuple[int, list]:
    items = []
    page = 1
    total = None
    while True:
        data = _search(query, page)
        if total is None:
            total = data.get("total_count", 0)
        page_items = data.get("items", [])
        items.extend(page_items)
        if len(page_items) < 100:
            break
        if page * 100 >= min(total, 1000):
            break
        page += 1
    return total or 0, items


def _fetch_range(kind: str, start: date, end: date) -> list:
    query = f"repo:cli/cli is:{kind} created:{start.isoformat()}..{end.isoformat()}"
    total, items = _fetch_all(query)
    if total < 1000:
        return items
    # Split date range if search API limit is hit.
    if start >= end:
        return items
    mid = start + (end - start) // 2
    left = _fetch_range(kind, start, mid)
    right = _fetch_range(kind, mid + timedelta(days=1), end)
    return left + right


def _parse_ts(ts: str | None) -> datetime | None:
    if not ts:
        return None
    return datetime.fromisoformat(ts.replace("Z", "+00:00"))


def _has_bug_label(labels: list) -> bool:
    for label in labels or []:
        name = label.get("name", "")
        if "bug" in name.lower():
            return True
    return False


# Pull requests
pr_items = _fetch_range("pr", START_DATE, END_DATE)

pr_total = len(pr_items)
pr_merged = 0
pr_closed = 0
merge_days = []
contrib_counts = {}

for item in pr_items:
    user = item.get("user") or {}
    login = user.get("login") or "unknown"
    contrib_counts[login] = contrib_counts.get(login, 0) + 1

    created_at = _parse_ts(item.get("created_at"))
    pr_info = item.get("pull_request") or {}
    merged_at = _parse_ts(pr_info.get("merged_at"))

    if merged_at:
        pr_merged += 1
        if created_at:
            merge_days.append((merged_at - created_at).total_seconds() / 86400.0)
    else:
        if item.get("state") == "closed":
            pr_closed += 1

if merge_days:
    avg_merge = round(sum(merge_days) / len(merge_days), 1)
else:
    avg_merge = 0.0

if contrib_counts:
    top_contributor = sorted(contrib_counts.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
else:
    top_contributor = ""

# Issues
issue_items = _fetch_range("issue", START_DATE, END_DATE)

issue_total = len(issue_items)
issue_bug = 0
resolved_bugs = 0

for item in issue_items:
    labels = item.get("labels", [])
    if _has_bug_label(labels):
        issue_bug += 1
        closed_at = _parse_ts(item.get("closed_at"))
        if closed_at:
            if START_DATE <= closed_at.date() <= END_DATE:
                resolved_bugs += 1

report = {
    "pr": {
        "total": pr_total,
        "merged": pr_merged,
        "closed": pr_closed,
        "avg_merge_days": avg_merge,
        "top_contributor": top_contributor,
    },
    "issue": {
        "total": issue_total,
        "bug": issue_bug,
        "resolved_bugs": resolved_bugs,
    },
}

with open("/app/report.json", "w", encoding="utf-8") as f:
    json.dump(report, f, indent=2)
    f.write("\n")

print(json.dumps(report, indent=2))
